# --- Route /decouvrir ---
def router(s):
    if "Discover" in s: return s
    s = s.replace('import Home from "../views/Home.vue";', 'import Home from "../views/Home.vue";\nimport Discover from "../views/Discover.vue";', 1)
    s = s.replace('  { path: "/categorie/:slug"', '  { path: "/decouvrir", name: "discover", component: Discover },\n  { path: "/categorie/:slug"', 1)
    return s
rw("storefront/src/router/index.js", router)

# --- Style mobile chargé après le thème ---
def main(s):
    if "ios-mobile.css" in s: return s
    return s.replace('import "./assets/theme.css";', 'import "./assets/theme.css";\nimport "./assets/ios-mobile.css";', 1)
rw("storefront/src/main.js", main)

# --- En-tête : bouton recherche (mobile) + recherche qui fonctionne partout ---
def header(s):
    if "hact-search" not in s:
        s = s.replace('<button class="menu-toggle"', '''<router-link to="/decouvrir" class="hact hact-search" aria-label="Rechercher">
            <svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg>
          </router-link>
          <button class="menu-toggle"''', 1)
    s = re.sub(r'function doSearch\(\) \{.*?\n\}', '''function doSearch() {
  const v = search.value.trim();
  if (!v) return;
  router.push({ path: "/decouvrir", query: { q: v } });
  search.value = "";
  menuOpen.value = false;
}''', s, count=1, flags=re.S)
    return s
rw("storefront/src/components/SiteHeader.vue", header)
